/**
 * Templates Management Page
 */

import { useState, useEffect } from "react";
import { Link, useNavigate } from "react-router-dom";
import { templateApi } from "../services/handoverApi";
import type { ChecklistTemplate } from "../types/handover";

export function TemplatesPage() {
  const navigate = useNavigate();
  const [templates, setTemplates] = useState<ChecklistTemplate[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [deleteConfirm, setDeleteConfirm] = useState<string | null>(null);

  useEffect(() => {
    loadTemplates();
  }, []);

  const loadTemplates = async () => {
    try {
      setIsLoading(true);
      const data = await templateApi.listTemplates();
      setTemplates(data);
    } catch (error) {
      console.error("Failed to load templates:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleDelete = async (templateId: string) => {
    try {
      await templateApi.deleteTemplate(templateId);
      setTemplates((prev) => prev.filter((t) => t.id !== templateId));
      setDeleteConfirm(null);
    } catch (error) {
      console.error("Failed to delete template:", error);
    }
  };

  const handleStartCheckout = (templateId: string) => {
    navigate(`/checkout?template=${templateId}`);
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="size-8 spinner" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 pb-4 border-b border-[#dadce0]">
        <div>
          <h1 className="text-xl font-semibold text-[#202124]">テンプレート管理</h1>
          <p className="text-sm text-[#5f6368] mt-1">
            チェックリストのテンプレートを作成・管理します
          </p>
        </div>
        <Link to="/templates/new" className="btn btn-primary shrink-0">
          <svg className="size-4 mr-1.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" aria-hidden="true">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
          </svg>
          新規作成
        </Link>
      </div>

      {/* Templates Grid */}
      {templates.length > 0 ? (
        <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-4">
          {templates.map((template) => (
            <div
              key={template.id}
              className="card p-4 group flex flex-col h-full"
            >
              <div className="flex items-start justify-between mb-3">
                <div className="flex-1 min-w-0">
                  <h3 className="font-medium text-[#202124] text-sm truncate">
                    {template.title}
                  </h3>
                  <p className="text-xs text-[#5f6368] mt-1 line-clamp-2">
                    {template.description || "説明なし"}
                  </p>
                </div>
                <button
                  onClick={() => setDeleteConfirm(template.id)}
                  aria-label="テンプレートを削除"
                  className="p-1.5 text-[#9aa0a6] hover:text-[#d93025] hover:bg-red-50 rounded sm:opacity-0 sm:group-hover:opacity-100 transition-all"
                >
                  <svg className="size-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" aria-hidden="true">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                  </svg>
                </button>
              </div>

              {/* Items Preview - flex-1 to fill available space */}
              <div className="flex-1">
                <div className="flex flex-wrap gap-1.5 mb-3">
                  {template.items?.slice(0, 4).map((item, idx) => (
                    <span
                      key={idx}
                      className="px-2 py-0.5 text-xs rounded bg-[#e8f0fe] text-[#1a73e8]"
                    >
                      {item.topic}
                    </span>
                  ))}
                  {(template.items?.length || 0) > 4 && (
                    <span className="px-2 py-0.5 text-xs bg-[#f1f3f4] text-[#9aa0a6] rounded">
                      +{(template.items?.length || 0) - 4}
                    </span>
                  )}
                </div>
              </div>

              {/* Stats */}
              <div className="flex items-center gap-3 text-xs text-[#5f6368] mb-3 tabular-nums">
                <span className="flex items-center gap-1">
                  <svg className="size-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" aria-hidden="true">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" />
                  </svg>
                  {template.items?.length || 0}項目
                </span>
                <span className="flex items-center gap-1">
                  <svg className="size-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" aria-hidden="true">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                  </svg>
                  約{Math.round((template.duration || 600) / 60)}分
                </span>
              </div>

              {/* Actions - mt-auto to push to bottom */}
              <div className="flex gap-2 pt-3 border-t border-[#dadce0] mt-auto">
                <button
                  onClick={() => handleStartCheckout(template.id)}
                  className="btn btn-primary flex-1 text-xs py-1.5"
                >
                  使用する
                </button>
                <Link
                  to={`/templates/${template.id}/edit`}
                  className="btn btn-secondary text-xs py-1.5"
                >
                  編集
                </Link>
              </div>
            </div>
          ))}
        </div>
      ) : (
        <div className="card p-8 text-center">
          <div className="size-16 rounded-lg bg-[#f1f3f4] flex items-center justify-center mx-auto mb-4">
            <svg className="size-8 text-[#9aa0a6]" fill="none" viewBox="0 0 24 24" stroke="currentColor" aria-hidden="true">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 5a1 1 0 011-1h14a1 1 0 011 1v2a1 1 0 01-1 1H5a1 1 0 01-1-1V5zM4 13a1 1 0 011-1h6a1 1 0 011 1v6a1 1 0 01-1 1H5a1 1 0 01-1-1v-6zM16 13a1 1 0 011-1h2a1 1 0 011 1v6a1 1 0 01-1 1h-2a1 1 0 01-1-1v-6z" />
            </svg>
          </div>
          <h3 className="text-base font-medium text-[#202124] mb-1">
            テンプレートがありません
          </h3>
          <p className="text-sm text-[#5f6368] mb-4">
            AIと対話しながらチェックリストのテンプレートを作成しましょう。
          </p>
          <Link to="/templates/new" className="btn btn-primary">
            テンプレートを作成
          </Link>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {deleteConfirm && (
        <div className="modal-overlay">
          <div className="modal-content">
            <div className="text-center">
              <div className="size-12 rounded-lg bg-red-50 flex items-center justify-center mx-auto mb-4">
                <svg className="size-6 text-[#d93025]" fill="none" viewBox="0 0 24 24" stroke="currentColor" aria-hidden="true">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                </svg>
              </div>
              <h3 className="text-lg font-semibold text-[#202124] mb-2">
                テンプレートを削除しますか？
              </h3>
              <p className="text-sm text-[#5f6368] mb-6">
                この操作は取り消せません。
              </p>
              <div className="flex gap-3 justify-center">
                <button
                  onClick={() => setDeleteConfirm(null)}
                  className="btn btn-secondary"
                >
                  キャンセル
                </button>
                <button
                  onClick={() => handleDelete(deleteConfirm)}
                  className="btn bg-[#d93025] text-white hover:bg-red-700"
                >
                  削除する
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * Tenant Onboarding Page - Create or join a tenant
 */

import { useState, useEffect } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";
import { clsx } from "clsx";
import { useAuth } from "../contexts/AuthContext";
import {
  createTenant,
  getInvitationByToken,
  acceptInvitation,
  type Invitation,
} from "../lib/firebase";

type OnboardingTab = "create" | "join";

export function TenantOnboardingPage() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const { user, tenant, needsTenantSetup, refreshUserRole, refreshUserTenants, signOut, isLoading: authLoading } = useAuth();

  const [activeTab, setActiveTab] = useState<OnboardingTab>("create");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);

  // Create tenant form state
  const [tenantName, setTenantName] = useState("");

  // Join tenant form state
  const [inviteToken, setInviteToken] = useState("");
  const [invitation, setInvitation] = useState<Invitation | null>(null);
  const [isLoadingInvitation, setIsLoadingInvitation] = useState(false);

  // Check for invite token in URL
  useEffect(() => {
    const token = searchParams.get("token");
    if (token) {
      setInviteToken(token);
      setActiveTab("join");
      loadInvitation(token);
    }
  }, [searchParams]);

  // Redirect if user already has a tenant
  useEffect(() => {
    if (!authLoading && tenant && !needsTenantSetup) {
      navigate("/", { replace: true });
    }
  }, [authLoading, tenant, needsTenantSetup, navigate]);

  const loadInvitation = async (token: string) => {
    setIsLoadingInvitation(true);
    setError(null);
    setInvitation(null);

    try {
      const result = await getInvitationByToken(token);
      if (result) {
        setInvitation(result);
      } else {
        setError("招待が見つからないか、有効期限が切れています");
      }
    } catch (err: any) {
      console.error("Failed to load invitation:", err);
      setError(err.message || "招待の読み込みに失敗しました");
    } finally {
      setIsLoadingInvitation(false);
    }
  };

  const handleCreateTenant = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!tenantName.trim()) {
      setError("組織名を入力してください");
      return;
    }

    setIsSubmitting(true);
    setError(null);

    try {
      await createTenant(tenantName.trim());
      setSuccess("組織を作成しました");
      await refreshUserRole();       // 最新のuserRecordを取得→tenantId付きでテナント情報更新
      await refreshUserTenants();    // userTenantsリスト更新→needsTenantSetup=false
      // useEffectが自動的に"/"へ遷移
    } catch (err: any) {
      console.error("Failed to create tenant:", err);
      setError(err.message || "組織の作成に失敗しました");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleAcceptInvitation = async () => {
    if (!inviteToken) {
      setError("招待トークンを入力してください");
      return;
    }

    setIsSubmitting(true);
    setError(null);

    try {
      await acceptInvitation(inviteToken);
      setSuccess("組織に参加しました");
      await refreshUserRole();       // 最新のuserRecordを取得→tenantId付きでテナント情報更新
      await refreshUserTenants();    // userTenantsリスト更新→needsTenantSetup=false
      // useEffectが自動的に"/"へ遷移
    } catch (err: any) {
      console.error("Failed to accept invitation:", err);
      setError(err.message || "招待の受諾に失敗しました");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleTokenChange = (token: string) => {
    setInviteToken(token);
    setInvitation(null);
    setError(null);
  };

  const handleLookupInvitation = () => {
    if (inviteToken.trim()) {
      loadInvitation(inviteToken.trim());
    }
  };

  if (authLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[#f8f9fa]">
        <div className="size-8 spinner" />
      </div>
    );
  }

  if (!user) {
    navigate("/login", { replace: true });
    return null;
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-[#f8f9fa] px-4">
      <div className="w-full max-w-md">
        {/* Logo and Title */}
        <div className="text-center mb-8">
          <div className="inline-flex items-center justify-center size-16 bg-primary-600 text-white rounded-2xl mb-4">
            <svg className="size-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" />
            </svg>
          </div>
          <h1 className="text-2xl font-bold text-[#202124]">組織の設定</h1>
          <p className="text-[#5f6368] mt-2">
            新しい組織を作成するか、招待を受けて参加してください
          </p>
        </div>

        {/* Card */}
        <div className="bg-white rounded-xl border border-[#dadce0] shadow-sm overflow-hidden">
          {/* Tabs */}
          <div className="flex border-b border-[#dadce0]">
            <button
              onClick={() => { setActiveTab("create"); setError(null); setSuccess(null); }}
              className={clsx(
                "flex-1 py-3 text-sm font-medium transition-colors",
                activeTab === "create"
                  ? "text-primary-600 border-b-2 border-primary-600 bg-primary-50/50"
                  : "text-[#5f6368] hover:text-[#202124] hover:bg-[#f8f9fa]"
              )}
            >
              新規作成
            </button>
            <button
              onClick={() => { setActiveTab("join"); setError(null); setSuccess(null); }}
              className={clsx(
                "flex-1 py-3 text-sm font-medium transition-colors",
                activeTab === "join"
                  ? "text-primary-600 border-b-2 border-primary-600 bg-primary-50/50"
                  : "text-[#5f6368] hover:text-[#202124] hover:bg-[#f8f9fa]"
              )}
            >
              招待から参加
            </button>
          </div>

          <div className="p-6">
            {/* Error Message */}
            {error && (
              <div className="mb-4 p-3 bg-red-50 border border-red-200 rounded-lg text-sm text-[#d93025]">
                {error}
              </div>
            )}

            {/* Success Message */}
            {success && (
              <div className="mb-4 p-3 bg-green-50 border border-green-200 rounded-lg text-sm text-green-700">
                {success}
              </div>
            )}

            {activeTab === "create" ? (
              <>
                <h2 className="text-lg font-medium text-[#202124] text-center mb-6">
                  新しい組織を作成
                </h2>

                <form onSubmit={handleCreateTenant} className="space-y-4">
                  <div>
                    <label htmlFor="tenantName" className="block text-sm font-medium text-[#202124] mb-1">
                      組織名
                    </label>
                    <input
                      id="tenantName"
                      type="text"
                      value={tenantName}
                      onChange={(e) => setTenantName(e.target.value)}
                      placeholder="例: 株式会社サンプル"
                      className="input"
                      disabled={isSubmitting}
                    />
                    <p className="mt-1 text-xs text-[#5f6368]">
                      組織名は後から変更できます
                    </p>
                  </div>

                  <button
                    type="submit"
                    disabled={isSubmitting || !tenantName.trim()}
                    className="w-full btn btn-primary py-3 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    {isSubmitting ? (
                      <span className="flex items-center justify-center gap-2">
                        <div className="size-4 spinner border-white/30 border-t-white" />
                        作成中...
                      </span>
                    ) : (
                      "組織を作成"
                    )}
                  </button>
                </form>

                <div className="mt-4 p-3 bg-[#f8f9fa] rounded-lg">
                  <p className="text-xs text-[#5f6368]">
                    <strong>組織を作成すると:</strong>
                  </p>
                  <ul className="mt-2 text-xs text-[#5f6368] space-y-1">
                    <li>・ あなたが組織のオーナーになります</li>
                    <li>・ 他のメンバーを招待できます</li>
                    <li>・ テンプレートやデータを管理できます</li>
                  </ul>
                </div>
              </>
            ) : (
              <>
                <h2 className="text-lg font-medium text-[#202124] text-center mb-6">
                  招待から組織に参加
                </h2>

                <div className="space-y-4">
                  <div>
                    <label htmlFor="inviteToken" className="block text-sm font-medium text-[#202124] mb-1">
                      招待トークン
                    </label>
                    <div className="flex gap-2">
                      <input
                        id="inviteToken"
                        type="text"
                        value={inviteToken}
                        onChange={(e) => handleTokenChange(e.target.value)}
                        placeholder="招待トークンを入力"
                        className="input flex-1"
                        disabled={isSubmitting || isLoadingInvitation}
                      />
                      <button
                        type="button"
                        onClick={handleLookupInvitation}
                        disabled={isSubmitting || isLoadingInvitation || !inviteToken.trim()}
                        className="btn btn-secondary disabled:opacity-50"
                      >
                        {isLoadingInvitation ? (
                          <div className="size-4 spinner" />
                        ) : (
                          "確認"
                        )}
                      </button>
                    </div>
                    <p className="mt-1 text-xs text-[#5f6368]">
                      管理者から受け取った招待トークンを入力してください
                    </p>
                  </div>

                  {/* Invitation Details */}
                  {invitation && (
                    <div className="p-4 bg-[#f8f9fa] border border-[#dadce0] rounded-lg">
                      <h3 className="text-sm font-medium text-[#202124] mb-2">
                        招待の詳細
                      </h3>
                      <div className="space-y-2 text-sm">
                        <div className="flex justify-between">
                          <span className="text-[#5f6368]">組織名:</span>
                          <span className="text-[#202124] font-medium">
                            {invitation.tenantName || invitation.tenantId}
                          </span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-[#5f6368]">権限:</span>
                          <span className="text-[#202124]">
                            {invitation.role === "admin" ? "管理者" :
                             invitation.role === "user" ? "一般ユーザー" : "参照ユーザー"}
                          </span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-[#5f6368]">有効期限:</span>
                          <span className="text-[#202124]">
                            {new Date(invitation.expiresAt).toLocaleString("ja-JP")}
                          </span>
                        </div>
                      </div>
                    </div>
                  )}

                  <button
                    type="button"
                    onClick={handleAcceptInvitation}
                    disabled={isSubmitting || !invitation}
                    className="w-full btn btn-primary py-3 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    {isSubmitting ? (
                      <span className="flex items-center justify-center gap-2">
                        <div className="size-4 spinner border-white/30 border-t-white" />
                        参加中...
                      </span>
                    ) : (
                      "組織に参加"
                    )}
                  </button>
                </div>

                <div className="mt-4 p-3 bg-[#f8f9fa] rounded-lg">
                  <p className="text-xs text-[#5f6368]">
                    <strong>招待トークンについて:</strong>
                  </p>
                  <ul className="mt-2 text-xs text-[#5f6368] space-y-1">
                    <li>・ 組織の管理者から招待トークンを受け取ります</li>
                    <li>・ トークンには有効期限があります</li>
                    <li>・ 参加後は指定された権限でアクセスできます</li>
                  </ul>
                </div>
              </>
            )}
          </div>
        </div>

        {/* Footer */}
        <div className="mt-6 text-center">
          <p className="text-xs text-[#9aa0a6] mb-3">
            ログイン中: {user.email}
          </p>
          <button
            onClick={() => signOut()}
            className="text-sm text-[#5f6368] hover:text-[#202124] underline"
          >
            ログアウト
          </button>
        </div>
      </div>
    </div>
  );
}

